// Package generated classifies paths and content headers that commonly identify
// generated files. It never reads the filesystem.
package generated

import (
	"bytes"
	"strings"
)

// Confidence describes how specifically a rule identifies generated content.
type Confidence int

const (
	Weak Confidence = iota
	Strong
)

// Match explains which rule classified a path.
type Match struct {
	Category   string
	Confidence Confidence
	Rule       string
}

var strongSegments = map[string]string{
	"node_modules":  "dependencies",
	"__pycache__":   "cache",
	".next":         "build-output",
	".nuxt":         "build-output",
	".gradle":       "cache",
	".pytest_cache": "cache",
	".mypy_cache":   "cache",
	".nyc_output":   "coverage",
	"htmlcov":       "coverage",
	".terraform":    "dependencies",
}

var weakSegments = map[string]string{
	"coverage": "coverage",
	"dist":     "build-output",
	"build":    "build-output",
	"out":      "build-output",
	"target":   "build-output",
	"vendor":   "dependencies",
	"bin":      "build-output",
	"obj":      "build-output",
	".cache":   "cache",
}

var fileRules = []struct {
	suffix, category string
	confidence       Confidence
}{
	{".pyc", "cache", Strong}, {".pyo", "cache", Strong},
	{".class", "build-output", Strong}, {".o", "build-output", Weak},
	{".obj", "build-output", Weak}, {".exe", "build-output", Weak},
	{".dll", "build-output", Weak}, {".so", "build-output", Weak},
	{".dylib", "build-output", Weak}, {".min.js", "build-output", Weak},
	{".min.css", "build-output", Weak}, {".map", "build-output", Weak},
	{".log", "logs", Weak},
}

// Classify normalizes separators and a leading ./ before matching whole path
// segments or filename rules. Strong matches take precedence over weak
// matches. Directory rules require a directory segment; callers
// can identify a directory itself with a trailing slash. Rule is the matched
// segment, filename, or wildcard pattern (for example, node_modules or *.pyc).
func Classify(path string) (Match, bool) {
	path = strings.TrimPrefix(strings.ReplaceAll(path, "\\", "/"), "./")
	segments := strings.Split(path, "/")
	for _, segment := range segments {
		if category, ok := strongSegments[segment]; ok {
			return Match{category, Strong, segment}, true
		}
	}
	name := segments[len(segments)-1]
	for _, special := range []string{".DS_Store", "Thumbs.db"} {
		if strings.EqualFold(name, special) {
			return Match{"metadata", Strong, special}, true
		}
	}
	for _, rule := range fileRules {
		if strings.HasSuffix(name, rule.suffix) {
			return Match{rule.category, rule.confidence, "*" + rule.suffix}, true
		}
	}
	for _, segment := range segments[:len(segments)-1] {
		if category, ok := weakSegments[segment]; ok {
			return Match{category, Weak, segment}, true
		}
	}
	return Match{}, false
}

// ClassifyContent checks lines in the first 2048 bytes for generated-code
// markers. A NUL anywhere in that prefix rejects the input as binary. Bytes
// beyond the prefix are never inspected, including for binary detection.
func ClassifyContent(head []byte) (Match, bool) {
	head = head[:min(len(head), 2048)]
	if bytes.IndexByte(head, 0) >= 0 {
		return Match{}, false
	}
	for _, line := range strings.Split(string(head), "\n") {
		var rule string
		switch {
		case strings.Contains(line, "Code generated") && strings.Contains(line, "DO NOT EDIT"):
			rule = "Code generated ... DO NOT EDIT"
		case strings.Contains(line, "@generated"):
			rule = "@generated"
		default:
			lower := strings.ToLower(line)
			switch {
			case strings.Contains(lower, "this file was automatically generated"):
				rule = "This file was automatically generated"
			case strings.Contains(lower, "auto-generated by"):
				rule = "auto-generated by"
			}
		}
		if rule != "" {
			return Match{Category: "generated-code", Confidence: Strong, Rule: rule}, true
		}
	}
	return Match{}, false
}
